    case 2:
        emit_rex_wrb(b, 1, dst, base);
        emit_byte(b, 0x0F);
        emit_byte(b, is_unsigned ? 0xB7 : 0xBF);
        emit_modrm_disp(b, dst, base, off);
        break;
    case 4:
        emit_rex_if(b, 0, dst, 0, base);
        emit_byte(b, 0x8B);
        emit_modrm_disp(b, dst, base, off);
