            runtime.memset(&gv, 0, sizeof(gv));
            gv.name = g->name;
            gv.file = (char *)g->loc.file;
            gv.line = g->loc.line;
            gv.kind = DBG_VAR_GLOBAL;
            gv.type_tag = DBG_TY_INT;
            gv.width = g->size;
            gv.is_unsigned = 0;
            gv.loc_kind = DBG_LOC_ADDR;
